module iir3_v9 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] y2;
  wire [31:0] a0 = (37 * x) & 16'hFFFF;
  wire [31:0] a1 = (62 * x + r1) & 16'hFFFF;
  wire [31:0] a2 = (53 * x + r2) & 16'hFFFF;
  wire [31:0] a3 = (36 * x + r3) & 16'hFFFF;
  wire [31:0] y3 = ((9 * y + a0)>>4) & 16'hFFFF;
  wire [31:0] y4 = ((5 * y2 + a1)>>4) & 16'hFFFF;
  always @(posedge clk) begin
    if (!rst_n) begin y<=0; y2<=0; r1<=0; r2<=0; r3<=0; end
    else begin
      y <= a3;
      y2 <= y3;
      r1 <= a0;
      r2 <= a1;
      r3 <= a2;
    end
  end
endmodule

